INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('loonghao/vx/vx-usage', 'community', 'loonghao', 'vx', 'loonghao/vx', 'vx-usage', 0, 0, 40, '2026-03-02T01:56:11.127Z', '2026-03-02T03:41:22.425Z', 'eeb6c7950d24461d1be3ab5416c9114468568256ae5349d1afb3f61aa51b3408', '{"id":"loonghao/vx/vx-usage","name":"vx-usage","description":{"zh":"vx-usage 是一个通用开发工具管理器，支持多种技术和框架","ja":"vx-usageは、複数の技術とフレームワークをサポートするユニバーサル開発ツールマネージャーです","ko":"vx-usage는 여러 기술과 프레임워크를 지원하는 유니버설 개발 도구 관리자입니다","es":"vx-usage es una herramienta de desarrollo universal que ayuda a los desarrolladores a gestionar sus proyectos de manera eficiente. Ofrece una amplia gama de funciones para mejorar la productividad.","fr":"vx-usage est un outil de développement universel qui aide les développeurs à gérer leurs projets de manière efficace. Il offre une large gamme de fonctionnalités pour améliorer la productivité.","de":"vx-usage ist ein universelles Entwicklungstool, das Entwicklern hilft, ihre Projekte effizient zu verwalten. Es bietet eine breite Palette von Funktionen, um die Produktivität zu verbessern.","pt":"O vx-usage é um Gerenciador de Ferramentas de Desenvolvimento Universal, projetado para simplificar o processo de codificação","ru":"ИИ Агенты vx-usage - Универсальный Менеджер для разработчиков, упрощающий процесс кодирования","ar":"vx-usage هو مدير أدوات تطوير عالمي مصمم لتبسيط عملية البرمجة","en":"Universal Development Tool Manager"},"seo":{"title":{"zh":"vx-usage AI工具：通用开发工具管理","ja":"vx-usage AIエージェント：ユニバーサル開発ツールマネージャー","ko":"vx-usage AI 에이전트: 유니버설 개발 도구 관리자","es":"Herramienta Universal de Desarrollo vx-usage - Agentes de IA","fr":"Outil de Développement Universel vx-usage - Outils d''IA","de":"Universelles Entwicklungstool vx-usage - KI-Tools","pt":"Ferramentas de Desenvolvimento Universal - vx-usage","ru":"ИИ Агенты: Универсальный Менеджер vx-usage","ar":"أدوات تطوير عالمية - vx-usa